"""Dump a practice session compactly: python trace.py SID [--bo] [--full]"""
import json
import os
import sys
import urllib.request

KEY = os.environ["ARENA_API_KEY"]
CACHE = "/private/tmp/claude-501/-Users-linuspummer-Documents-coding-vibe-coding-munich-ehl-2026-final/cc83f96a-079c-4a98-95f6-010d3ef3e252/scratchpad/cache"
os.makedirs(CACHE, exist_ok=True)


def get(path):
    f = os.path.join(CACHE, path.replace("/", "_") + ".json")
    if os.path.exists(f):
        return json.load(open(f))
    req = urllib.request.Request("https://arena.tacto.ai/v1/" + path, headers={"X-API-Key": KEY})
    d = json.load(urllib.request.urlopen(req))
    json.dump(d, open(f, "w"))
    return d


def terms_str(t):
    return " ".join(f"{k}={v}" for k, v in sorted(t.items()))


def main():
    sid = sys.argv[1]
    full = "--full" in sys.argv
    s = get(f"sessions/{sid}")
    if "--keys" in sys.argv:
        print(list(s.keys()))
        print(json.dumps(s)[:3000])
        return
    r = s.get("result") or {}
    print(s.get("case_id"), "score", r.get("score"), "c_open", r.get("c_open"), "c_deal", r.get("c_deal"), "c_best", r.get("c_best"))
    for ev in s.get("trace") or []:
        who = ev.get("from") or ev.get("role") or ev.get("kind")
        sup = ev.get("supplier_id", "")
        msg = ev.get("message") or ev
        body = msg.get("body") or msg.get("text") or ""
        sheets = msg.get("term_sheets") or []
        print(f"--- r{ev.get('round')} {sup} {who} status={ev.get('status') or msg.get('status')}")
        if full:
            print(body)
        else:
            print(body[:600].replace("\n", " | "))
        for sh in sheets:
            print("   SHEET", sh.get("id", ""), terms_str(sh.get("terms", {})))
        for k in ("claims", "checks", "signals"):
            if msg.get(k):
                print("  ", k, json.dumps(msg[k])[:400])
    if "--bo" in sys.argv:
        bo = get(f"sessions/{sid}/backoffice")
        print("===== BACKOFFICE")
        for e in bo:
            if e.get("to") == "team" or "call" in e.get("text", ""):
                print(f"r{e['round']} {e['supplier_id']} {e['from']}->{e['to']}: {e['text'][:300]}")


main()

